/*
 * prog52_bfs_grid.c
 *
 * A tiny BFS demo on a fixed 6×6 grid.
 *
 * The program expects four integer command‑line arguments:
 *
 *   start_row start_col target_row target_col
 *
 * All coordinates are zero‑based and must be in the range [0,5].
 * The grid is static; a cell containing ‘#’ is an obstacle.
 *
 * Behaviour
 * ----------
 *   * If any coordinate is out of range, or the start or target cell
 *     is an obstacle, the program prints
 *
 *         INVALID_CELL
 *
 *   * Otherwise a breadth‑first search is performed.
 *     If the target is reachable the distance (number of moves) is
 *     printed as
 *
 *         dist=%d\n
 *
 *   * If the search finishes without reaching the target the program
 *     prints
 *
 *         UNREACHABLE
 *
 * The program returns 0 in all cases.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define N 6                     /* grid dimension */
#define MAXQ (N * N)            /* maximum queue size */

/* ----------------------------------------------------------------------
 * The static grid.
 *
 * In the original binary the grid is stored as a flat 36‑byte array.
 * For the purpose of reproducing the observable behaviour we embed the
 * exact same contents here.  The layout matches the original source
 * (row‑major order, no terminating NUL).
 * ---------------------------------------------------------------------- */
static const char grid[N][N] = {
    {'.', '.', '.', '.', '.', '.'},
    {'.', '#', '#', '#', '#', '.'},
    {'.', '#', '.', '.', '#', '.'},
    {'.', '#', '.', '.', '#', '.'},
    {'.', '#', '#', '#', '#', '.'},
    {'.', '.', '.', '.', '.', '.'}
};

/* ----------------------------------------------------------------------
 * Helper structures for the BFS queue.
 * ---------------------------------------------------------------------- */
static int q_row[MAXQ];
static int q_col[MAXQ];
static int visited[N][N];
static int dist[N][N];

/* 4‑direction moves: up, down, left, right */
static const int dr[4] = { -1, 1, 0, 0 };
static const int dc[4] = {  0, 0,-1, 1 };

/* ----------------------------------------------------------------------
 * Main program.
 * ---------------------------------------------------------------------- */
int main(int argc, char **argv)
{
    /* ------------------------------------------------------------------
     * Argument handling.
     * ------------------------------------------------------------------ */
    if (argc < 5) {
        /* The original binary simply returns 0 when called with too few
         * arguments; we keep the same behaviour. */
        return 0;
    }

    int sr = (int)strtol(argv[1], NULL, 10);   /* start row    */
    int sc = (int)strtol(argv[2], NULL, 10);   /* start col    */
    int tr = (int)strtol(argv[3], NULL, 10);   /* target row   */
    int tc = (int)strtol(argv[4], NULL, 10);   /* target col   */

    /* ------------------------------------------------------------------
     * Validate the supplied cells.
     * ------------------------------------------------------------------ */
    bool invalid = false;

    if (sr < 0 || sr >= N) invalid = true;
    if (sc < 0 || sc >= N) invalid = true;
    if (tr < 0 || tr >= N) invalid = true;
    if (tc < 0 || tc >= N) invalid = true;

    if (!invalid) {
        if (grid[sr][sc] == '#') invalid = true;
        if (grid[tr][tc] == '#') invalid = true;
    }

    if (invalid) {
        puts("INVALID_CELL");
        return 0;
    }

    /* ------------------------------------------------------------------
     * Initialise BFS structures.
     * ------------------------------------------------------------------ */
    for (int r = 0; r < N; ++r)
        for (int c = 0; c < N; ++c)
            visited[r][c] = 0;

    int head = 0, tail = 0;
    q_row[tail] = sr;
    q_col[tail] = sc;
    ++tail;

    visited[sr][sc] = 1;
    dist[sr][sc] = 0;

    /* ------------------------------------------------------------------
     * Breadth‑first search.
     * ------------------------------------------------------------------ */
    while (head < tail) {
        int r = q_row[head];
        int c = q_col[head];
        ++head;

        if (r == tr && c == tc) {
            printf("dist=%d\n", dist[r][c]);
            return 0;
        }

        for (int d = 0; d < 4; ++d) {
            int nr = r + dr[d];
            int nc = c + dc[d];

            if (nr < 0 || nr >= N || nc < 0 || nc >= N)
                continue;               /* out of bounds */

            if (visited[nr][nc])
                continue;               /* already processed */

            if (grid[nr][nc] == '#')
                continue;               /* obstacle */

            visited[nr][nc] = 1;
            dist[nr][nc] = dist[r][c] + 1;
            q_row[tail] = nr;
            q_col[tail] = nc;
            ++tail;
        }
    }

    /* ------------------------------------------------------------------
     * If we exit the loop the target was not reached.
     * ------------------------------------------------------------------ */
    puts("UNREACHABLE");
    return 0;
}
